mapper.sql:
WHERE i.factory_code IS NOT NULL AND i.status <> 'PENDING_ALLOC'


    AND 1=0
    AND i.factory_code IN #{x}


AND i.pi_no = #{f.pi} AND i.bill_no = #{f.bill}
AND i.bill_seq = #{f.billSeq} AND i.material_code = #{f.material}
AND i.material_code = #{f.material}
AND (i.seq_pi_no, i.seq_dec) >= (#{f.fromPi}, #{f.fromDec})
AND (i.seq_pi_no, i.seq_dec) <= (#{f.toPi}, #{f.toDec})
AND i.sn LIKE #{f.q}


    AND i.attach_no IS NULL
    AND i.attach_no = #{f.attach}

mapper.select:
SELECT i.sn, i.rule_version_id, i.pi_no, i.factory_code, f.factory_name, i.bill_seq, i.material_code, i.attach_no, i.length_text, i.seq_pi_no, i.seq_dec, i.status, i.delivery_mode, i.delivery_batch_no, i.suspend FROM sn_item i LEFT JOIN sn_factory f ON f.factory_code = i.factory_code ORDER BY
FIELD(i.attach_no, #{a}),
i.bill_seq, i.seq_pi_no, i.seq_dec LIMIT #{offset}, #{size}
